                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    if (i + 5 < str.length()) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                            i += 5;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('u');
                            i++;
                        }
                    } else {
                        sb.append('\\').append('u');
                        i++;
                    }
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int end = j;
                        while (end < str.length() && end - j < 3 && str.charAt(end) >= '0' && str.charAt(end) <= '7') {
                            end++;
                        }
                        String oct = str.substring(j, end);
                        try {
                            int code = Integer.parseInt(oct, 8);
                            sb.append((char) code);
                            i = end - 1;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append(next);
                            i++;
                        }
                    } else {
                        sb.append(next);
                        i++;
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

