protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) return null;
    Set<E> remaining = new HashSet<>(tour);
    Iterator<E> it = remaining.iterator();
    E first = it.next();
    it.remove();
    V start = graph.getEdgeSource(first);
    V current = graph.getEdgeTarget(first);
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    vertices.add(start);
    vertices.add(current);
    edges.add(first);
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> iter = remaining.iterator();
        while (iter.hasNext()) {
            E e = iter.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current)) {
                vertices.add(tgt);
                edges.add(e);
                current = tgt;
                iter.remove();
                found = true;
                break;
            } else if (tgt.equals(current)) {
                vertices.add(src);
                edges.add(e);
                current = src;
                iter.remove();
                found = true;
                break;
            }
        }
        if (!found) break;
    }
    double weight = 0.0;
    for (E e : edges) weight += graph.getEdgeWeight(e);
    return new GraphWalk<>(graph, start, current, vertices, edges, weight);
}

