    if (this.head == null) {
        this.head = list.head;
        this.tail = list.tail;
        this.size += list.size;
    } else {
        // Link the tail of this list to the head of the source list
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
        this.size += list.size;
    }
